// 搜索参数模型
export class SearchParams {
  constructor(data) {
    this.question = data.question;
    this.topicIds = data.topic_ids || data.topicId ? [data.topicId] : [];
    this.deepSeek = data.deep_seek !== undefined ? data.deep_seek : true;
    this.refs = data.refs || false;
    this.history = data.history || [];
    this.topK = data.top_k || 10;
    this.intentRewrite = data.intent_rewrite || false;
    this.selectMatrix = data.select_matrix || false;
  }

  validate() {
    if (!this.question) {
      throw new Error('Question is required');
    }
    
    if (this.topicIds.length === 0) {
      throw new Error('At least one topic_id is required');
    }
    
    if (this.topicIds.length > 1) {
      logger.warn('Currently only one topic_id is supported, using the first one');
      this.topicIds = [this.topicIds[0]];
    }
    
    return true;
  }

  toJSON() {
    return {
      question: this.question,
      topic_ids: this.topicIds,
      deep_seek: this.deepSeek,
      refs: this.refs,
      history: this.history,
      top_k: this.topK,
      intent_rewrite: this.intentRewrite,
      select_matrix: this.selectMatrix
    };
  }
}

// 搜索结果模型
export class SearchResult {
  constructor(data) {
    this.answers = data.c?.answers || '';
    this.deepSeek = data.deep_seek;
    this.refs = data.refs;
    this.msgType = data.msg_type;
    this.retry = data.retry;
    this.refList = data.data?.ref_list || [];
    this.thinkingTime = data.data?.thinking_time;
    this.thinkingProcess = data.data?.thinking_process;
  }

  static fromStreamData(data) {
    const result = new SearchResult({});
    result.msgType = data.msg_type;
    result.retry = data.retry;
    
    if (data.msg_type === 1) {
      result.answers = data.data?.msg || '';
    } else if (data.msg_type === 105) {
      result.refList = data.data?.ref_list || [];
    } else if (data.msg_type === 22) {
      result.thinkingTime = data.data?.msg;
    } else if (data.msg_type === 21) {
      result.thinkingProcess = (result.thinkingProcess || '') + data.data?.msg;
    }
    
    return result;
  }
}

// 召回结果模型
export class RecallResult {
  constructor(data) {
    this.items = (data.c?.data || []).map(item => new RecallItem(item));
  }
}

export class RecallItem {
  constructor(data) {
    this.id = data.id;
    this.title = data.title;
    this.content = data.content;
    this.score = data.score;
    this.type = data.type; // FILE, NOTE, BLOGGER
    this.recallSource = data.recall_source; // embedding, keyword
  }
}